import { useCart } from "./CartContext";

const OrderList = () => {
    const { orders } = useCart(); // Get the orders from context

    // If no orders, show message
    if (!orders || orders.length === 0) {
        return <p>Chưa có đơn hàng nào.</p>;
    }

    return (
        <div className="order-list">
            <h2>📦 Đơn hàng đã đặt</h2>
            {orders.map((order) => (
                <div key={order.id} className="order-item">
                    <h3>🆔 Đơn hàng #{order.id}</h3>
                    <p>📅 Ngày đặt: {order.date}</p>
                    <p>💵 Tổng tiền: {order.total}k</p>

                    {/* Loop through items of the order */}
                    <div className="order-items">
                        {order.items.map((item, index) => (
                            <div key={index} className="order-item-details">
                                <img
                                    src={item.image}
                                    alt={item.name}
                                    className="order-item-image"
                                />
                                <div className="order-item-info">
                                    <span>{item.name}</span>
                                    <span>{item.price}k</span>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            ))}
        </div>
    );
};

export default OrderList;
